def knowledge_page():
    from lyn_unmatched import ISSUES
    st.subheader('מרכז ידע – שאלות ותשובות')
    st.caption('לחצי על השאלה לפתיחת התשובה. ניתן לחפש לפי מילת מפתח.')
    search = st.text_input('חיפוש במרכז הידע', key='lyn_faq_search').strip().casefold()
    entries = FAQ + [('טיפול באי־שיוכים', title, '\n'.join(f'{i}. {step}' for i,step in enumerate(info['steps'],1)), '') for title,info in ISSUES.items()]
    matches = [entry for entry in entries if search in ' '.join(entry).casefold()]
    for category in dict.fromkeys(e[0] for e in matches):
        st.markdown('### ' + category)
        for _,question,answer,note in (e for e in matches if e[0]==category):
            with st.expander(question):
                if note: st.warning(note)
                st.markdown(answer)
    if not matches: st.info('לא נמצאו שאלות מתאימות. אפשר לשאול את עוזר ה-AI.')

def faq_context():
    return '\n\nמרכז ידע LYN:\n' + '\n\n'.join(f'שאלה: {q}\nתשובה: {a}\nמעמד: {n or "נוהל פנימי שנמסר על ידי מנהל התפעול"}' for _,q,a,n in FAQ)
